tests:
test({ sr: 'obični tipovi kao typeof', en: 'ordinary types like typeof' }, () => {
  expect(describeType(5)).toBe('number');
  expect(describeType('hi')).toBe('string');
  expect(describeType(true)).toBe('boolean');
});
test({ sr: 'null je "null"', en: 'null is "null"' }, () => {
  expect(describeType(null)).toBe('null');
});
test({ sr: 'niz je "array"', en: 'an array is "array"' }, () => {
  expect(describeType([1, 2])).toBe('array');
});

hiddenTests:
test('undefined', () => {
  expect(describeType(undefined)).toBe('undefined');
});
test('a plain object stays "object"', () => {
  expect(describeType({ a: 1 })).toBe('object');
});
test('an empty array is still an array', () => {
  expect(describeType([])).toBe('array');
});
test('a function and NaN', () => {
  expect(describeType(() => 1)).toBe('function');
  expect(describeType(NaN)).toBe('number');
});
test('a date is an object, like typeof says', () => {
  expect(describeType(new Date(0))).toBe('object');
});

solutions.code:
function describeType(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}
